<script>
const S = __DATA__;
const eur = x => x == null ? "-" : "€" + Math.round(x).toLocaleString("en");
const esc = s => String(s ?? "").replace(/[&<>]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;"}[c]));
const pct = x => x == null ? "-" : (100 * x).toFixed(0);
function list() {
  const q = document.getElementById("q").value.toLowerCase();
  document.getElementById("list").innerHTML = S.map((s, i) => [s, i])
    .filter(([s]) => JSON.stringify([s.case_id, s.title, s.set, s.variant, s.threads.map(t => t.supplier_id)]).toLowerCase().includes(q))
    .map(([s, i]) => `<div class="item" data-i="${i}"><span class="score">${pct(s.result.score)}</span>
      <b>${esc(s.case_id)}</b> ${esc(s.set)}${s.variant ? " · " + esc(s.variant) : ""}
      <small>${esc(s.title)}</small><small>${s.result.deal ? "deal " + esc(s.result.supplier_id) : esc(s.end || "no deal")} · ${esc(s.file.split("_")[1])}</small></div>`).join("");
  document.querySelectorAll(".item").forEach(e => e.onclick = () => show(+e.dataset.i));
}
function sheets(ev) {
  if (!ev.sheets.length) return "";
  const keys = [...new Set(ev.sheets.flatMap(s => Object.keys(s.terms)))];
  const fmt = v => v && typeof v === "object" ? `${v.series} ${v.material_share * 100}% db ${v.deadband_pct}` : esc(v ?? "-");
  return `<table><tr>${keys.map(k => `<th>${esc(k)}</th>`).join("")}<th>C</th></tr>` +
